// In-app custom sections become named slices on the main-thread track.
import androidx.tracing.Trace

fun loadFeed() {
    Trace.beginSection("loadFeed")
    try { repository.load() } finally { Trace.endSection() }
}

@RunWith(AndroidJUnit4::class)
class StartupBenchmark {
    @get:Rule val rule = MacrobenchmarkRule()

    @Test
    fun coldStartupWithProfile() = rule.measureRepeated(
        packageName = "com.example.app",
        metrics = listOf(StartupTimingMetric()),
        iterations = 10,
        startupMode = StartupMode.COLD,
        compilationMode = CompilationMode.Partial(),   // AOT only profile-covered code
    ) {
        pressHome()
        startActivityAndWait()
    }
}

@Composable
fun FeedScreen(uiState: FeedUiState) {
    // Derived value recomputes only when uiState.items changes identity.
    val visible by remember(uiState.items) {
        derivedStateOf { uiState.items.filter { it.visible } }
    }
    LazyColumn {
        items(visible, key = { it.id }) { item -> FeedRow(item) }
    }
}

